特性 公平锁 非公平锁 获取顺序 FIFO 随机/插队 吞吐量 较低 较高 饥饿问题 无 可能 复杂度 较复杂 较简单 <pre><code>public class FairAndUnfairDemo {
    private static final ReentrantLock fairLock = new ReentrantLock(true);
    private static final ReentrantLock unfairLock = new ReentrantLock(false);

    public static void fairTask() {
        fairLock.lock();
        try {
            System.out.println(Thread.currentThread().getName() + " 获取了锁");
        } finally {
            fairLock.unlock();
        }
    }

    public static void unfairTask() {
        unfairLock.lock();
        try {
            System.out.println(Thread.currentThread().getName() + " 获取了锁");
        } finally {
            unfairLock.unlock();
        }
    }

    public static void main(String[] args) {
        System.out.println("==========公平锁测试==========");
        for (int i = 1; i &lt;= 3; i++) {
            new Thread(() -&gt; fairTask(), "T" + i).start();
        }

        try {
            Thread.sleep(1000);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        System.out.println("==========非公平锁测试==========");
        for (int i = 1; i &lt;= 3; i++) {
            new Thread(() -&gt; unfairTask(), "T" + i).start();
        }
    }
}
</code></pre>
